/**
 * https://leetcode.com/problems/single-number/
 * Time O(N) | Space O(1)
 * @param {number[]} nums
 * @return {number}
 */
var singleNumber = function (nums, xor = 0) {
  for (num of nums) {
    xor ^= num;
  }
  return xor;
};

solutions.java:
//We can use xor operation as it cancel out itself (i.e. only when values are different in binary representation then give output). See how xor operation works if confused.
class Solution {

    public int singleNumber(int[] nums) {
        int ans = nums[0];
        for (int i = 1; i < nums.length; i++) ans ^= nums[i];
        return ans;
    }
}

solutions.cpp:
/*
    Given int array, every element appears twice except 1, find it
    Ex. nums = [2,2,1] -> 1, nums = [4,1,2,1,2] -> 4

    a XOR a returns 0, so returns 0 for all except the unique one

    Time: O(n)
    Space: O(1)
*/

class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int result = 0;

        for (int i = 0; i < nums.size(); i++) {
            result = result ^ nums[i];
        }

        return result;
    }
};
